import {
  JupyterFrontEnd,
  JupyterFrontEndPlugin
} from '@jupyterlab/application';

import {
  ILayoutRestorer
} from '@jupyterlab/application';

import {
  IFileType,
  DocumentRegistry,
  DocumentWidget
} from '@jupyterlab/docregistry';

import {
  IMainMenu
} from '@jupyterlab/mainmenu';

import {
  GalyleoPanel
} from './widget';

import { dashboardIcon } from './icon';

/**
 * Galyleo file type registration
 */
const galyleoFileType: Partial<IFileType> = {
  name: 'galyleo-dashboard',
  displayName: 'Galyleo Dashboard',
  extensions: ['.gd.json'],
  mimeTypes: ['application/json'],
  fileFormat: 'text',
  contentType: 'file'
};

/**
 * The extension plugin
 */
const extension: JupyterFrontEndPlugin<void> = {
  id: 'galyleo-extension',
  autoStart: true,
  requires: [IMainMenu, ILayoutRestorer],
  activate: (
    app: JupyterFrontEnd,
    mainMenu: IMainMenu,
    restorer: ILayoutRestorer
  ) => {
    const { docRegistry } = app;

    // Add the file type
    docRegistry.addFileType(galyleoFileType);

    // Register the widget factory
    const galyleoWidgetFactory = new DocumentRegistry.WidgetFactory<GalyleoPanel>({
      name: 'Galyleo',
      fileTypes: ['galyleo-dashboard'],
      defaultFor: ['galyleo-dashboard'],
      readOnly: true,           // This disables JupyterLab's internal save
      canStartKernel: false     // We're not a kernel-backed document
    });

    // Suppress Lab’s default file menu behavior
    galyleoWidgetFactory.widgetCreated.connect((sender, widget) => {
      widget.title.icon = dashboardIcon;

      // Disable context-based save/revert
      widget.context.save = async () => {};
      widget.context.revert = async () => {};
      Object.defineProperty(widget.context.model, 'dirty', {
        get: () => false,
        set: () => {}
      });
    });

    // Add the widget factory
    docRegistry.addWidgetFactory(galyleoWidgetFactory);

    // Register panel creation
    galyleoWidgetFactory.widgetCreated.connect((sender, widget) => {
      restorer.add(widget, widget.id);
    });

    galyleoWidgetFactory.registerExtension('GalyleoPanel', {
      createNew: (context) => {
        return new GalyleoPanel(context);
      }
    });
  }
};

export default extension;
```

